/* Optional experimental local pupil-motion tracking. No remote model, no
   recording, no retention. Accuracy is limited by light, head movement and
   camera quality; never triggers navigation without a separate user click. */
(()=>{'use strict';const $=id=>document.getElementById(id),app=window.NexusApp;if(!app)return;
const video=$('camera'),overlay=$('cameraCanvas'),oc=overlay.getContext('2d'),buf=document.createElement('canvas');buf.width=320;buf.height=240;const bc=buf.getContext('2d',{willReadFrequently:true});
let stream=null,raf=0,eyes=[],samples=[],points=[],matrix=null,last=0,lastGaze=null;
const targetPositions=[[.18,.22],[.82,.22],[.50,.50],[.18,.79],[.82,.79]];
function say(s){$('gazeStatus').textContent=s;}
function clearHighlight(){app.state.gaze=null;document.querySelectorAll('.world').forEach(x=>x.classList.remove('gaze'));$('gazeDot').classList.add('hidden');}
function stop(){if(raf)cancelAnimationFrame(raf);raf=0;for(const track of stream?.getTracks()||[])track.stop();stream=null;video.srcObject=null;eyes=[];samples=[];points=[];matrix=null;oc.clearRect(0,0,320,240);$('calibrate').disabled=true;$('calibration').classList.add('hidden');clearHighlight();say('Camera off. No frames or gaze data were saved.');}
$('closeGaze').onclick=()=>{stop();$('gazePanel').classList.add('hidden');};$('stopCamera').onclick=stop;
$('startCamera').onclick=async()=>{if(stream)return;if(!navigator.mediaDevices?.getUserMedia){say('Camera access is not available. Pointer and touch remain functional.');return;}
 try{stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:'user',width:{ideal:320},height:{ideal:240}},audio:false});video.srcObject=stream;await video.play();say('Tap the center of each eye in the mirrored video.');tick();}catch(e){stop();say('Camera not started: permission denied or unavailable. Touch remains available.');}};
function pupil(frame,c){const [cx,cy]=c;let sum=0,xs=0,ys=0;const radX=18,radY=11;
 let brightness=0,n=0;for(let y=-radY;y<=radY;y+=2){for(let x=-radX;x<=radX;x+=2){if(x*x/(radX*radX)+y*y/(radY*radY)>1)continue;const xx=Math.round(cx+x),yy=Math.round(cy+y);if(xx<0||xx>=320||yy<0||yy>=240)continue;const i=(yy*320+xx)*4;brightness+=frame[i]*.25+frame[i+1]*.65+frame[i+2]*.1;n++;}}
 const avg=n?brightness/n:100;for(let y=-radY;y<=radY;y++){for(let x=-radX;x<=radX;x++){if(x*x/(radX*radX)+y*y/(radY*radY)>1)continue;const xx=Math.round(cx+x),yy=Math.round(cy+y);if(xx<0||xx>=320||yy<0||yy>=240)continue;const i=(yy*320+xx)*4;const v=frame[i]*.25+frame[i+1]*.65+frame[i+2]*.1;const weight=Math.max(0,avg-v-8);sum+=weight;xs+=xx*weight;ys+=yy*weight;}}
 return sum>130?{x:xs/sum,y:ys/sum}:null;}
function sample(){if(!stream||video.readyState<2||eyes.length!==2)return null;bc.drawImage(video,0,0,320,240);const frame=bc.getImageData(0,0,320,240).data;const p=eyes.map(e=>pupil(frame,e));if(p.some(x=>!x))return null;return{x:(p[0].x+p[1].x)/2,y:(p[0].y+p[1].y)/2};}
function solve3(A,b){const m=A.map((row,i)=>[...row,b[i]]);for(let i=0;i<3;i++){let best=i;for(let j=i+1;j<3;j++)if(Math.abs(m[j][i])>Math.abs(m[best][i]))best=j;if(Math.abs(m[best][i])<1e-8)return null;[m[i],m[best]]=[m[best],m[i]];const div=m[i][i];for(let k=i;k<4;k++)m[i][k]/=div;for(let j=0;j<3;j++){if(j===i)continue;const f=m[j][i];for(let k=i;k<4;k++)m[j][k]-=f*m[i][k];}}return m.map(row=>row[3]);}
function fit(data){const A=[[0,0,0],[0,0,0],[0,0,0]],bx=[0,0,0],by=[0,0,0];for(const p of data){const f=[p.x,p.y,1];for(let i=0;i<3;i++){bx[i]+=f[i]*p.sx;by[i]+=f[i]*p.sy;for(let j=0;j<3;j++)A[i][j]+=f[i]*f[j];}}const x=solve3(A,bx),y=solve3(A,by);return x&&y?{x,y}:null;}
function tick(now=0){raf=requestAnimationFrame(tick);if(!stream||document.hidden||now-last<70)return;last=now;
 oc.clearRect(0,0,320,240);for(const e of eyes){oc.beginPath();oc.ellipse(e[0],e[1],18,11,0,0,Math.PI*2);oc.strokeStyle='#c5f6e7';oc.lineWidth=1.5;oc.stroke();}
 const p=sample();if(p){samples.push(p);if(samples.length>25)samples.shift();if(matrix&&$('calibration').classList.contains('hidden')){const x=Math.max(.03,Math.min(.97,matrix.x[0]*p.x+matrix.x[1]*p.y+matrix.x[2]));const y=Math.max(.03,Math.min(.97,matrix.y[0]*p.x+matrix.y[1]*p.y+matrix.y[2]));lastGaze=lastGaze?{x:lastGaze.x*.78+x*.22,y:lastGaze.y*.78+y*.22}:{x,y};const px=lastGaze.x*innerWidth,py=lastGaze.y*innerHeight;const dot=$('gazeDot');dot.classList.remove('hidden');dot.style.left=px+'px';dot.style.top=py+'px';let chosen=null,dmin=130;for(const w of app.getScreenWorlds()){const d=Math.hypot(w.x-px,w.y-py);if(d<dmin){chosen=w.id;dmin=d;}}app.state.gaze=chosen;document.querySelectorAll('.world').forEach(b=>b.classList.toggle('gaze',b.dataset.world===chosen));}}}
overlay.addEventListener('pointerdown',e=>{if(!stream)return;const r=overlay.getBoundingClientRect();const x=(1-(e.clientX-r.left)/r.width)*320,y=(e.clientY-r.top)/r.height*240;if(eyes.length===2)eyes=[];eyes.push([x,y]);if(eyes.length===2){$('calibrate').disabled=false;say('Eyes marked. Choose Calibrate, then look at and tap each of the five points.');}else say('First eye marked. Tap the center of the second eye.');});
function placeTarget(){const [x,y]=targetPositions[points.length];const b=$('calTarget');b.style.left=x*100+'%';b.style.top=y*100+'%';b.setAttribute('aria-label','Record calibration point '+(points.length+1)+' of 5');}
$('calibrate').onclick=()=>{if(eyes.length!==2||!stream)return;points=[];samples=[];$('calibration').classList.remove('hidden');placeTarget();say('Calibrating locally.');};
$('calTarget').onclick=()=>{const s=samples.slice(-12);if(s.length<3){say('Hold your gaze on the point briefly, then tap again.');return;}const p={x:s.reduce((a,b)=>a+b.x,0)/s.length,y:s.reduce((a,b)=>a+b.y,0)/s.length,sx:targetPositions[points.length][0],sy:targetPositions[points.length][1]};points.push(p);samples=[];if(points.length<5){placeTarget();return;}matrix=fit(points);$('calibration').classList.add('hidden');say(matrix?'Experimental gaze highlighting active. Selection still requires touch or click.':'Calibration failed. Try again with brighter, steady lighting.');};
document.addEventListener('visibilitychange',()=>{if(document.hidden)stop();});window.addEventListener('pagehide',stop);
})();
